function zeroFreeSplit(n: number): number[] {
  let m = n, a = 0, b = 0, p = 1;
  while (m > 0) {
    if (m === 1) { a += p; break; } // a lone leading 1 goes to a
    const d = m % 10;
    if (d >= 2) {
      a += p; b += (d - 1) * p;
      m = Math.floor(m / 10);
    } else {
      a += (1 + d) * p; b += 9 * p; // 10 = 1 + 9, 11 = 2 + 9
      m = (m - 10 - d) / 10;
    }
    p *= 10;
  }
  return [a, b];
}

